import{_ as t,c as n,j as e,a as _,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百零一章 布施供养一百锅食物","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/201第二百零一章 布施供养一百锅食物.md","filePath":"meditation/巴利文大藏经/201第二百零一章 布施供养一百锅食物.md"}'),o={name:"meditation/巴利文大藏经/201第二百零一章 布施供养一百锅食物.md"};function l(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百零一章-布施供养一百锅食物",tabindex:"-1"},[_("第二百零一章 布施供养一百锅食物 "),e("a",{class:"header-anchor",href:"#第二百零一章-布施供养一百锅食物","aria-label":'Permalink to "第二百零一章 布施供养一百锅食物"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部20相应4经/大口锅经(譬喻相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，一个人他早上布施供养一百锅食物，他中午再次布施供养一百锅食物，他傍晚又布施供养一百锅食物，这个人一天之中分三次总共布施供养三百锅食物，他由此获得的功德利益比不上他在早上、中午、傍晚生起善念、慈悲心获得的功德利益，甚至于他生起善念、慈悲心的时间只有挤一次牛奶那么短的时间，他生起善念、慈悲心获得的功德利益都远远的大于他一天之中早上、中午、傍晚总共布施供养三百锅食物的功德利益。",-1),e("p",null,"弟子们，因此，你们应该这样去修行：「我们要多生起善念，多生起慈悲心，这样能够让我们获得无量的功德利益！我们要养成生起善念、慈悲心的习惯，我们要让生起善念、慈悲心的行为如同吃饭喝水那样的平常。」弟子们，你们就应该这样去修行。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",l]]);export{u as __pageData,f as default};
